# -*- coding: utf-8 -*-
OT_DAYS_7 = [
{"day":143,"book":"Jeremiah","ref":"Jeremiah 1-6","title":"A Young Prophet, A People's Betrayal",
 "chapters":[
  ("Jer 1","Jeremiah is called and commissioned by God as a young man, appointed as a prophet 'to the nations' despite his hesitation about his youth."),
  ("Jer 2","God, through Jeremiah, charges Israel with abandoning Him, 'the spring of living water,' for broken cisterns of their own idolatrous making."),
  ("Jer 3","God likens Israel's unfaithfulness to marital adultery, yet extends a genuine invitation to return, promising restoration if they will only acknowledge their guilt."),
  ("Jer 4","Jeremiah pleads for genuine repentance ('circumcise your hearts') while describing the coming devastation from the north in vivid, terrifying imagery."),
  ("Jer 5","God indicts Judah's pervasive corruption at every social level, from the poor to the powerful, none genuinely knowing or following Him."),
  ("Jer 6","Jeremiah warns of coming siege and destruction, lamenting that the people have no shame left even as disaster approaches."),
 ],
 "themes":["God's call can come even to the young and hesitant, equipped by His own presence and word.","Abandoning the true source of life for lesser, self-made substitutes is a recurring human temptation."],
 "expositor":("kaiser","Kaiser observed that God's assurance to young Jeremiah -- 'I knew you before I formed you in the womb' -- roots prophetic calling in God's prior, sovereign knowledge rather than the prophet's own qualifications or confidence."),
 "reflect":"Is there a calling you've hesitated to embrace because you felt too young, unqualified, or inexperienced, the way Jeremiah initially did?"},

{"day":144,"book":"Jeremiah","ref":"Jeremiah 7-12","title":"A Den of Robbers",
 "chapters":[
  ("Jer 7","God confronts the people's false confidence in the temple's mere physical presence, famously calling it 'a den of robbers' -- later quoted by Jesus in His own temple cleansing."),
  ("Jer 8-9","Jeremiah laments Judah's persistent unfaithfulness and physical devastation, wishing his head were 'a spring of water' so he could weep continuously for his people."),
  ("Jer 10","Jeremiah again mocks the folly of idol worship compared to the living, sovereign LORD."),
  ("Jer 11-12","God reveals a plot against Jeremiah's own life by people from his hometown, and Jeremiah honestly questions God about the apparent prosperity of the wicked."),
 ],
 "themes":["Confidence in religious buildings or rituals, apart from genuine obedience, is a dangerous illusion.","Genuine spiritual leadership sometimes requires grieving deeply over a people's persistent unfaithfulness."],
 "expositor":("kaiser","Kaiser noted that Jesus' direct quotation of Jeremiah 7's 'den of robbers' language during His own temple cleansing shows He saw the same danger Jeremiah confronted centuries earlier: outward religious confidence substituting for genuine covenant faithfulness."),
 "reflect":"Is there a place, ritual, or religious routine you've come to trust in itself, rather than as a means of genuine relationship with God?"},

{"day":145,"book":"Jeremiah","ref":"Jeremiah 13-18","title":"A Potter's Sovereign Hand",
 "chapters":[
  ("Jer 13","A ruined linen belt symbolizes Judah's ruined pride, and Jeremiah warns of coming humiliation and exile."),
  ("Jer 14-15","Jeremiah intercedes for the people during a severe drought, though God instructs him not to pray for them because judgment is now certain."),
  ("Jer 16-17","Jeremiah is commanded to remain unmarried as a living symbol of coming devastation, and a well-known passage contrasts trusting in human strength versus trusting in the LORD."),
  ("Jer 18","The image of a potter reshaping marred clay illustrates God's sovereign right to shape and reshape nations according to their response to Him."),
 ],
 "themes":["Symbolic, sometimes costly, prophetic actions communicated God's message as powerfully as words.","Trusting human strength ultimately proves unreliable compared to trusting the LORD."],
 "expositor":("davis","Dale Ralph Davis-style analysis of Jeremiah's symbolic acts -- the ruined belt, remaining unmarried -- notes that these costly, embodied prophecies made God's message unavoidably vivid in a way mere verbal warning might not have achieved."),
 "reflect":"Jeremiah 17:5-8 contrasts trusting people versus trusting God, using the image of a shrub in the desert versus a tree by water. Which image better describes your current sources of security?"},

{"day":146,"book":"Jeremiah","ref":"Jeremiah 19-24","title":"Good Figs, Bad Figs",
 "chapters":[
  ("Jer 19-20","Jeremiah smashes a clay jar as a symbolic prophecy of Judah's coming destruction, resulting in his own arrest and beating, provoking one of his most anguished personal laments."),
  ("Jer 21-22","God pronounces judgment on Judah's current king and royal house for their injustice and idolatry."),
  ("Jer 23","Jeremiah condemns false prophets who speak comforting lies, while promising a coming righteous 'Branch' from David's line."),
  ("Jer 24","A vision of good and bad figs illustrates the surprising truth that the exiles, not those who remained in Jerusalem, represented God's ultimate plan for restoration."),
 ],
 "themes":["Speaking uncomfortable truth can bring real personal cost and persecution.","God's ultimate plan of restoration sometimes runs through unexpected people or circumstances."],
 "expositor":("kaiser","Kaiser observed that the vision of good and bad figs in Jeremiah 24 overturned the assumption that those who avoided exile were more favored by God -- showing that present circumstances don't always indicate who is actually within God's redemptive plan."),
 "reflect":"Is there an assumption you've made about who is 'favored' by God based on present circumstances that Jeremiah 24 might challenge?"},

{"day":147,"book":"Jeremiah","ref":"Jeremiah 25-30","title":"Seventy Years, and Seeking the City's Welfare",
 "chapters":[
  ("Jer 25","Jeremiah predicts a seventy-year period of exile under Babylon, after which God would judge Babylon in turn."),
  ("Jer 26-27","Jeremiah's temple sermon nearly gets him killed, and he wears a wooden yoke to dramatize submission to Babylon as God's appointed, temporary judgment."),
  ("Jer 28-29","Jeremiah confronts a false prophet's premature promises of quick deliverance, and writes a letter to the exiles urging them to settle in, build homes, and seek the welfare of Babylon while awaiting God's promised future return."),
  ("Jer 30","God promises Israel and Judah's future restoration despite the certainty of coming judgment, describing the 'time of Jacob's trouble' that will ultimately end in rescue."),
 ],
 "themes":["God's judgment has a purpose and a limit, even when it feels overwhelming in the moment.","Faithful living in difficult circumstances sometimes means settling in and seeking the welfare of even an unwelcome situation."],
 "expositor":("davis","Dale Ralph Davis observed that Jeremiah's letter urging the exiles to 'seek the welfare of the city' reframes exile not as a pause to endure passively but as a genuine, faithful life to be lived wherever God has currently placed them."),
 "reflect":"Is there a difficult 'exile' season in your own life where seeking to bless your current circumstances, rather than just waiting to escape them, would look like genuine faithfulness?"},

{"day":148,"book":"Jeremiah","ref":"Jeremiah 31-36","title":"A New Covenant Promised",
 "chapters":[
  ("Jer 31","Jeremiah delivers one of Scripture's most significant prophecies -- a coming 'new covenant' in which God's law would be written on hearts, not merely stone tablets."),
  ("Jer 32","Jeremiah, even while Jerusalem is under siege, obediently purchases a field as a prophetic sign of certain future restoration."),
  ("Jer 33","God promises further restoration and reaffirms His covenant faithfulness to David's line despite the coming judgment."),
  ("Jer 34-35","Jeremiah confronts Judah's broken promise to free Hebrew slaves, contrasting it with the faithful obedience of the Rekabite family to their ancestor's simple instructions."),
  ("Jer 36","King Jehoiakim arrogantly burns Jeremiah's scroll of prophecy, yet God has it rewritten with even more added."),
 ],
 "themes":["The promised new covenant, writing God's law on human hearts, anticipates the gospel's transforming power.","Faithful obedience sometimes means acting on God's promises even when present circumstances make them seem implausible."],
 "expositor":("kaiser","Kaiser has emphasized that Jeremiah 31's new covenant prophecy -- explicitly quoted in Hebrews 8 as fulfilled in Christ -- promises an internal transformation of the heart that the old covenant's external law could describe but never itself produce."),
 "reflect":"Jeremiah bought a field during a siege as an act of faith in God's future promise. Is there a step of faith you could take now, even while current circumstances seem to contradict it?"},

{"day":149,"book":"Jeremiah","ref":"Jeremiah 37-42","title":"Faithful Counsel Under Threat",
 "chapters":[
  ("Jer 37-38","Jeremiah is imprisoned and thrown into a muddy cistern for his unpopular warnings, yet is rescued and continues to counsel King Zedekiah honestly despite the danger."),
  ("Jer 39","Jerusalem finally falls to Babylon exactly as Jeremiah had long warned, and he himself is treated well by the conquering Babylonians."),
  ("Jer 40-41","The Babylonian-appointed governor Gedaliah is assassinated, throwing the remaining Judean community into further chaos and fear."),
  ("Jer 42","The frightened remnant asks Jeremiah for guidance, promising to obey, yet already planning to disregard whatever God actually says."),
 ],
 "themes":["Faithful counsel sometimes requires speaking hard truth even at great personal risk.","God's warnings, however clearly given, don't guarantee they'll be heeded, even by those who ask for guidance."],
 "expositor":("davis","Dale Ralph Davis observed that the remnant's request for guidance in Jeremiah 42, followed by their immediate disregard of it, illustrates a recurring biblical pattern: asking for God's will while having already decided not to follow it if inconvenient."),
 "reflect":"Have you ever asked God for guidance while already having decided what you intended to do regardless of His answer?"},

{"day":150,"book":"Jeremiah","ref":"Jeremiah 43-48","title":"Fleeing to Egypt Anyway",
 "chapters":[
  ("Jer 43-44","The remnant disobeys God's clear instruction and flees to Egypt, taking Jeremiah with them, and continues practicing idolatry even in exile."),
  ("Jer 45","A brief, personal message comforts Jeremiah's scribe Baruch amid his own discouragement over the difficult ministry they share."),
  ("Jer 46-48","Oracles pronounce judgment against Egypt, the Philistines, and Moab, showing God's sovereignty extends over these surrounding nations as well."),
 ],
 "themes":["Disobeying God's clear instruction, even out of understandable fear, leads to compounded difficulty.","God's sovereignty extends over every surrounding nation, not merely His covenant people."],
 "expositor":("kaiser","Kaiser noted that the remnant's flight to Egypt in Jeremiah 43-44, directly disobeying God's explicit instruction to remain in the land, shows how fear can override even clear, recently-received divine guidance."),
 "reflect":"Is there an area where fear might be tempting you to override guidance you already know to be true?"},

{"day":151,"book":"Jeremiah","ref":"Jeremiah 49-52","title":"Babylon's Certain Fall, History's Confirmation",
 "chapters":[
  ("Jer 49-50","Oracles continue against Ammon, Edom, Damascus, and finally an extended prophecy against Babylon itself, promising its eventual downfall."),
  ("Jer 51","The lengthy prophecy against Babylon concludes, and the scroll containing it is symbolically sunk in the Euphrates River as a picture of Babylon's certain, permanent fall."),
  ("Jer 52","A historical appendix recounts Jerusalem's destruction and the exile in sober detail, closing the book by confirming everything Jeremiah had warned came true."),
 ],
 "themes":["God's judgment on even history's most powerful empires confirms His ultimate sovereignty over all nations.","The book's closing historical confirmation validates that Jeremiah's difficult, long-resisted warnings were entirely accurate."],
 "expositor":("kaiser","Kaiser observed that Jeremiah 52's closing historical appendix, matching the destruction Jeremiah predicted decades earlier, serves as the book's final vindication -- proving that the prophet so widely rejected in his lifetime had spoken God's truth all along."),
 "reflect":"Is there a long-resisted truth in your own life that, like Jeremiah's warnings, might eventually be vindicated even if it's currently unpopular or ignored?"},

{"day":152,"book":"Lamentations","ref":"Lamentations 1-5","title":"Mercies New Every Morning",
 "chapters":[
  ("Lam 1","Jerusalem is pictured as a grieving widow, abandoned and humiliated, mourning the devastating loss of her former glory."),
  ("Lam 2","The poet describes in painful detail the LORD's own hand in Jerusalem's destruction as deserved judgment for persistent covenant unfaithfulness."),
  ("Lam 3","At the very center of the book, amid overwhelming grief, comes one of Scripture's most quoted affirmations of hope: 'his mercies are new every morning; great is your faithfulness.'"),
  ("Lam 4","The poet continues describing the horrific extent of the siege and destruction's human cost, particularly its impact on children and the vulnerable."),
  ("Lam 5","The book closes with a prayer asking God to remember His people's suffering and restore them, ending without a fully resolved conclusion, reflecting ongoing, honest grief."),
 ],
 "themes":["Honest, structured grief before God is a legitimate, even necessary, response to devastating loss.","God's faithfulness and mercy remain steady even in the very center of overwhelming devastation."],
 "expositor":("davis","Dale Ralph Davis observed that Lamentations 3's declaration of hope sits deliberately at the literal center of the book's structure, surrounded on both sides by unrelenting grief -- showing that hope in God's faithfulness doesn't erase real sorrow, but can exist right in the middle of it."),
 "reflect":"Is there a grief you're carrying where you need to hold both honest sorrow and 'new every morning' hope together, rather than rushing past one for the other?"},

{"day":153,"book":"Ezekiel","ref":"Ezekiel 1-6","title":"A Mobile Throne, A Watchman's Charge",
 "chapters":[
  ("Ezek 1","Ezekiel receives an overwhelming, symbolic vision of God's mobile, glorious throne-chariot, emphasizing that God's presence is not confined to the Jerusalem temple alone."),
  ("Ezek 2-3","God commissions Ezekiel as a 'watchman' for Israel, giving him a scroll to eat symbolizing his prophetic message, and warning him of the exiles' stubborn resistance."),
  ("Ezek 4-5","Ezekiel performs a series of dramatic symbolic acts -- lying on his side for extended periods, shaving his head -- to vividly dramatize Jerusalem's coming siege and judgment."),
  ("Ezek 6","Ezekiel pronounces judgment specifically against Israel's idolatrous 'high places' scattered throughout the land."),
 ],
 "themes":["God's presence is not confined to any single physical location, even the temple.","Costly, symbolic obedience can communicate God's message more powerfully than words alone."],
 "expositor":("duguid","Duguid, whose scholarship focuses on Ezekiel, observed that the opening vision of God's mobile throne-chariot reassured the exiled community that God had not been left behind in a destroyed Jerusalem -- He was fully present with them even in Babylon."),
 "reflect":"Do you tend to associate God's presence with a specific place or routine, in a way Ezekiel's vision might helpfully challenge?"},

{"day":154,"book":"Ezekiel","ref":"Ezekiel 7-12","title":"Idolatry in the Temple, God's Glory Departs",
 "chapters":[
  ("Ezek 7","Ezekiel announces that 'the end has come' for Judah's persistent idolatry and violence."),
  ("Ezek 8-9","In a vision, Ezekiel witnesses the detestable idolatry actually occurring within the Jerusalem temple itself, followed by a vision of judgment falling on the city while a faithful remnant is marked for protection."),
  ("Ezek 10-11","God's glory departs from the temple in stages, symbolizing the tragic withdrawal of His presence, though He promises to be a 'sanctuary' for the scattered exiles."),
  ("Ezek 12","Ezekiel dramatizes the coming exile by symbolically packing his bags and digging through a wall, embodying the message he proclaims."),
 ],
 "themes":["Idolatry hidden within a sacred, respected space is especially serious in God's eyes.","God's departing presence is a tragic, gradual withdrawal, not an abrupt or careless abandonment."],
 "expositor":("duguid","Duguid noted that God's glory departing the temple in deliberate stages across chapters 10-11, rather than all at once, reflects His reluctance to abandon His dwelling place, even amid necessary judgment."),
 "reflect":"Is there an area of hidden compromise, like the idolatry Ezekiel saw within the temple itself, that looks respectable on the surface?"},

{"day":155,"book":"Ezekiel","ref":"Ezekiel 13-18","title":"False Comfort, Individual Responsibility",
 "chapters":[
  ("Ezek 13","Ezekiel condemns false prophets who offer false comfort, 'whitewashing' a flimsy wall with reassuring lies."),
  ("Ezek 14","God declares that even if Noah, Daniel, and Job themselves lived in Jerusalem, their righteousness would save only themselves, not the unrepentant nation."),
  ("Ezek 15-16","An allegory of a useless, burned vine and an extended, uncomfortable allegory of an unfaithful bride describe Jerusalem's persistent spiritual adultery."),
  ("Ezek 17","A parable of eagles and a vine illustrates the political entanglements and unfaithfulness of Judah's recent kings."),
  ("Ezek 18","God insists on individual responsibility for sin, rejecting the excuse that children merely inherit and are helplessly bound by their parents' guilt."),
 ],
 "themes":["False comfort that ignores real sin does more harm than honest warning.","Each individual bears personal responsibility for their own response to God, not merely their family's history."],
 "expositor":("duguid","Duguid observed that Ezekiel 18's insistence on individual responsibility corrected a fatalistic proverb the exiles were using to excuse their own sin by blaming their ancestors -- God holds each person accountable for their own response to Him."),
 "reflect":"Is there a pattern you've excused as simply 'inherited' from family or upbringing that Ezekiel 18 would call you to take personal responsibility for instead?"},

{"day":156,"book":"Ezekiel","ref":"Ezekiel 19-24","title":"The Limits of Patience",
 "chapters":[
  ("Ezek 19","A lament mourns the tragic downfall of Judah's recent kings, pictured as captured lion cubs and an uprooted vine."),
  ("Ezek 20","God reviews Israel's long history of rebellion since Egypt, despite His own repeated patience and provision."),
  ("Ezek 21-22","Ezekiel pronounces the certainty of Jerusalem's coming judgment by the sword, cataloging the city's pervasive sin and injustice at every social level."),
  ("Ezek 23","An extended allegory of two unfaithful sisters representing Israel and Judah illustrates their shared history of political and spiritual unfaithfulness."),
  ("Ezek 24","A boiling pot allegory and the sudden death of Ezekiel's own wife, which he is forbidden to publicly mourn, dramatize the shocking severity of the coming judgment."),
 ],
 "themes":["God's patience with persistent rebellion, though real, is not indefinite.","Sometimes God calls His messengers to costly, painful obedience that others may not understand."],
 "expositor":("duguid","Duguid pointed out that Ezekiel's forbidden public mourning for his own wife in chapter 24 was itself a living prophecy -- his personal restraint from normal grief dramatized the depth of shock Jerusalem's fall would cause, too devastating even for customary mourning rituals."),
 "reflect":"Has God ever asked you for a costly, misunderstood form of obedience, the way He did with Ezekiel's personal grief?"},

{"day":157,"book":"Ezekiel","ref":"Ezekiel 25-30","title":"Judgment on the Surrounding Nations",
 "chapters":[
  ("Ezek 25-28","Oracles pronounce judgment against surrounding nations -- Ammon, Moab, Edom, Philistia, Tyre, and Sidon -- for their hostility and pride, including an extended lament over Tyre's fallen splendor."),
  ("Ezek 29-30","Oracles pronounce judgment against Egypt for its unreliable, false promises of help to Judah."),
 ],
 "themes":["God's justice extends to how nations treat each other, including pride and hostility toward His people.","Even great, glorious cities and civilizations remain fully subject to God's sovereign judgment."],
 "expositor":("duguid","Duguid observed that the extended lament over Tyre's fallen splendor in Ezekiel 27-28 reflects genuine grief over the tragedy of judgment, even while affirming its necessity -- God's justice is never portrayed as gleeful, even toward the guilty."),
 "reflect":"When you consider deserved consequences for wrongdoing, either yours or someone else's, do you hold both justice and genuine sorrow together, the way this lament models?"},

{"day":158,"book":"Ezekiel","ref":"Ezekiel 31-36","title":"Failed Shepherds, a New Heart Promised",
 "chapters":[
  ("Ezek 31-32","Further oracles against Egypt use the image of a once-towering, now-felled great tree, and extended laments describe Egypt's coming downfall among the nations already in the grave."),
  ("Ezek 33","Ezekiel is recommissioned as a watchman following news of Jerusalem's fall, again emphasizing personal responsibility for repentance."),
  ("Ezek 34","God condemns Israel's failed shepherds (leaders) and promises to personally shepherd His scattered flock, ultimately through a coming Davidic ruler."),
  ("Ezek 35-36","Judgment is pronounced on Edom for its hostility, while God promises to cleanse Israel, give them 'a new heart and a new spirit,' and restore the land for His own name's sake."),
 ],
 "themes":["Failed human leadership can still be redeemed by God's own personal, promised shepherding.","God's motivation for restoration is ultimately about His own name and character, not merely Israel's merit."],
 "expositor":("duguid","Duguid noted that Ezekiel 36's promise of a 'new heart and new spirit' anticipates the same transformation Jeremiah's new covenant describes, and both find their fulfillment in the Spirit's work made possible through Christ."),
 "reflect":"Ezekiel 34 condemns failed shepherds and promises God will personally shepherd His people. Where do you most need to trust God's direct care rather than relying on flawed human leadership?"},

{"day":159,"book":"Ezekiel","ref":"Ezekiel 37-42","title":"Dry Bones Live Again",
 "chapters":[
  ("Ezek 37","The famous vision of the valley of dry bones dramatically pictures Israel's national and spiritual resurrection, coming together and receiving God's breath of life."),
  ("Ezek 38-39","An extended prophecy describes a future invasion by Gog and Magog, decisively defeated by God to vindicate His holiness before the nations."),
  ("Ezek 40-42","Ezekiel receives an extraordinarily detailed vision of a future restored temple, measured precisely by a heavenly guide."),
 ],
 "themes":["God can bring startling, complete restoration even to what seems utterly, hopelessly dead.","God's ultimate purpose in both judgment and restoration is that the nations would know He is the LORD."],
 "expositor":("duguid","Duguid observed that the valley of dry bones vision addressed the exiles' own despairing words -- 'our bones are dried up, our hope is gone' -- transforming their specific hopelessness into a vivid picture of God's power to restore what seems completely beyond recovery."),
 "reflect":"Is there an area of your life that feels like 'dry bones' -- completely beyond hope of restoration -- that this vision might speak fresh hope into?"},

{"day":160,"book":"Ezekiel","ref":"Ezekiel 43-48","title":"The LORD Is There",
 "chapters":[
  ("Ezek 43","God's glory dramatically returns to fill the new temple, reversing the earlier departure described in chapters 10-11."),
  ("Ezek 44-46","Detailed regulations govern the new temple's priesthood, offerings, and worship practices."),
  ("Ezek 47","A symbolic river flows from the temple, growing deeper and bringing life and healing wherever it flows, even into the Dead Sea."),
  ("Ezek 48","The land is allotted among the twelve tribes around the temple, and the book closes with the new city's name: 'The LORD Is There.'"),
 ],
 "themes":["God's glory returning to dwell among His people reverses the earlier tragedy of His departure.","God's ultimate purpose is intimate, permanent presence with His people, pictured in the new city's very name."],
 "expositor":("duguid","Duguid noted that Ezekiel's closing vision, ending with the new city named 'The LORD Is There,' directly answers the book's earlier tragedy of God's glory departing -- promising that His presence, once withdrawn, will be permanently restored."),
 "reflect":"Ezekiel's whole book moves from God's departure to His permanent return. Where in your own spiritual journey might you be currently living -- departure, waiting, or restored presence?"},

{"day":161,"book":"Daniel","ref":"Daniel 1-4","title":"Convictions in a Pagan Court",
 "chapters":[
  ("Dan 1","Daniel and his three friends resolve not to defile themselves with the king's food, and God grants them extraordinary wisdom and favor in the Babylonian court."),
  ("Dan 2","Daniel interprets King Nebuchadnezzar's dream of a great statue, revealing God's sovereign plan for a succession of world empires eventually replaced by God's own eternal kingdom."),
  ("Dan 3","Daniel's three friends refuse to worship a golden image and are miraculously preserved unharmed in a fiery furnace, with a mysterious fourth figure seen among them."),
  ("Dan 4","King Nebuchadnezzar is humbled through a period of insanity after his own pride, until he acknowledges that 'the Most High is sovereign over all kingdoms.'"),
 ],
 "themes":["Resolving to maintain conviction, even in small matters, can lead to remarkable favor and influence.","God's sovereignty over history extends over the rise and fall of every human empire."],
 "expositor":("kaiser","Kaiser observed that Daniel's resolve not to defile himself 'with the royal food and wine' in chapter 1, a seemingly small dietary matter, established a pattern of conviction that shaped his entire, decades-long faithful witness in a pagan court."),
 "reflect":"Is there a seemingly small conviction where holding firm now might establish a pattern of faithfulness for much bigger tests later?"},

{"day":162,"book":"Daniel","ref":"Daniel 5-8","title":"Writing on the Wall, A Den of Lions",
 "chapters":[
  ("Dan 5","A mysterious hand writes on the wall during King Belshazzar's arrogant feast, and Daniel interprets it as a pronouncement of the kingdom's imminent fall to the Medes and Persians."),
  ("Dan 6","Daniel is thrown into a den of lions for continuing to pray to God despite a decree forbidding it, and is miraculously preserved unharmed."),
  ("Dan 7","Daniel receives an apocalyptic vision of four beasts representing successive world empires, followed by the 'Ancient of Days' and 'one like a son of man' receiving an everlasting kingdom."),
  ("Dan 8","Daniel receives a further vision of a ram and goat, detailing conflicts between future kingdoms, particularly foreshadowing events under the Medo-Persian and Greek empires."),
 ],
 "themes":["Pride, even in the most powerful rulers, invites God's humbling correction.","Faithful prayer and worship sometimes require willingness to risk severe, even fatal, consequences."],
 "expositor":("duguid","Duguid, whose scholarship also covers Daniel, observed that Daniel's continued practice of prayer in chapter 6, despite a specific decree forbidding it, models unwavering, visible conviction rather than quiet, private compromise when public faithfulness is directly tested."),
 "reflect":"Is there a situation where public pressure is tempting you toward quiet compromise rather than the visible faithfulness Daniel modeled?"},

{"day":163,"book":"Daniel","ref":"Daniel 9-12","title":"Seventy Weeks, and a Final Vision",
 "chapters":[
  ("Dan 9","Daniel prays an extended, humble prayer of confession for his people's sin, and receives the detailed 'seventy weeks' prophecy concerning Jerusalem's future and the coming Messiah."),
  ("Dan 10","Daniel receives a vision preceded by intense fasting and prayer, and glimpses something of the unseen spiritual conflict occurring behind earthly political events."),
  ("Dan 11","An extraordinarily detailed prophecy describes centuries of future conflict between northern and southern kingdoms, historically fulfilled with remarkable precision in the centuries following."),
  ("Dan 12","The book closes with a promise of final resurrection and vindication for the faithful, and Daniel is told to seal up the scroll 'until the time of the end.'"),
 ],
 "themes":["Genuine, humble confession of both personal and national sin often precedes significant revelation from God.","Unseen spiritual conflict often lies behind the visible political and historical events we observe."],
 "expositor":("kaiser","Kaiser noted that Daniel's prayer of confession in chapter 9, identifying with his people's sin even though he himself was personally blameless, models the kind of humble, corporate intercession that precedes significant movements of God in a nation's history."),
 "reflect":"Is there a corporate or communal sin -- in your church, community, or nation -- you could humbly identify with and intercede for, the way Daniel did for Israel?"},
]
